const rateLimiter = new RateLimiter(RATE_LIMIT_RPM);
const screenTool = new ScreenTool(client, cache, rateLimiter);
const fieldsTool = new FieldsTool();
const presetsTool = new PresetsTool();

// Start cache cleanup
cache.startCleanup();

// Create MCP server
const server = new Server(
  {
