        inputSchema: {
          type: "object",
          properties: {
            preset_name: {
              type: "string",
              description:
                "Name of preset: quality_stocks, value_stocks, dividend_stocks, momentum_stocks, growth_stocks",
            },
          },
          required: ["preset_name"],
        },
      },
      {
        name: "list_presets",
